BEGIN;
TRUNCATE branch_menu_prices, menu_items, branches, categories RESTART IDENTITY CASCADE;

SELECT setval('categories_id_seq',(SELECT MAX(id) FROM categories));

SELECT setval('branches_id_seq',(SELECT MAX(id) FROM branches));

SELECT setval('menu_items_id_seq',(SELECT MAX(id) FROM menu_items));

SELECT setval('branch_menu_prices_id_seq',(SELECT MAX(id) FROM branch_menu_prices));

COMMIT;
